            {"guild_level": 5, "kind": "spell", "name": "life drain"},
            {"guild_level": 7, "kind": "spell", "name": "blood brotherhood"},
            {"guild_level": 8, "kind": "spell", "name": "blood healing"},
            {"guild_level": 9, "kind": "spell", "name": "energy drain"},
