            {"guild_level": 1, "kind": "skill", "name": "worship of lloth"},
            {"guild_level": 2, "kind": "spell", "name": "summon spiders"},
            {"guild_level": 3, "kind": "spell", "name": "evil heart"},
            {"guild_level": 4, "kind": "spell", "name": "spin web"},
            {"guild_level": 5, "kind": "spell", "name": "silken parachute"},
            {"guild_level": 6, "kind": "spell", "name": "spider bite"},
            {"guild_level": 7, "kind": "spell", "name": "sacrifice to lloth"},
            {"guild_level": 8, "kind": "spell", "name": "appoint acolyte of lloth"},
