            {"guild_level": 7, "kind": "spell", "name": "arrow of light"},
            {"guild_level": 8, "kind": "skill", "name": "ceremony"},
            {"guild_level": 9, "kind": "skill", "name": "magical economy"},
            {"guild_level": 10, "kind": "spell", "name": "armor of faith"},
            {"guild_level": 11, "kind": "spell", "name": "remove scar"},
            {"guild_level": 11, "kind": "skill", "name": "holy essence"},
            {"guild_level": 13, "kind": "spell", "name": "cure serious wounds"},
